function device(string $u):array{$x=strtolower($u);$d=preg_match('/iphone|android|mobile|blackberry/',$x)?'Mobile':(preg_match('/ipad|tablet/',$x)?'Tablet':'Desktop');$b=str_contains($x,'chrome')&&!str_contains($x,'chromium')&&!str_contains($x,'edg')?'Chrome':(str_contains($x,'firefox')?'Firefox':(str_contains($x,'safari')&&!str_contains($x,'chrome')?'Safari':(str_contains($x,'edg')?'Edge':(str_contains($x,'opr')||str_contains($x,'opera')?'Opera':'Other'))));$o=str_contains($x,'windows')?'Windows':(str_contains($x,'mac os')?'macOS':(str_contains($x,'android')?'Android':(str_contains($x,'iphone')||str_contains($x,'ipad')?'iOS':(str_contains($x,'linux')?'Linux':'Other'))));return ['device'=>$d,'browser'=>$b,'os'=>$o];}
