function verifyhtml(string $t,string $endpoint='/api/verify'):string{global $C;$site=htmlspecialchars($C['site'],ENT_QUOTES);$t=htmlspecialchars($t,ENT_QUOTES);return '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Verify — TeamDev</title><script src="https://js.hcaptcha.com/1/api.js" async defer></script><style>body{margin:0;min-height:100vh;display:grid;place-items:center;background:#060810;color:#dde4f0;font:15px Arial}.card{width:min(420px,calc(100% - 32px));padding:30px;background:#0b0d18;border:1px solid #222840;border-radius:18px;text-align:center}h1{color:#00d4ff}p{color:#9aa5bd}.h-captcha{display:flex;justify-content:center;margin:24px 0}button{width:100%;padding:13px;border:0;border-radius:10px;background:linear-gradient(120deg,#00d4ff,#8b5cf6);color:white;font-weight:bold}button:disabled{opacity:.4}</style></head><body><main class="card"><h1>TeamDev</h1><h2>Verify Access</h2><p>Complete CAPTCHA to continue.</p><div class="h-captcha" data-sitekey="'.$site.'" data-callback="solved" data-theme="dark"></div><button id="btn" disabled onclick="go()">Continue</button></main><script>let c="";function solved(t){c=t;btn.disabled=false}async function go(){btn.disabled=true;try{let r=await fetch("'.$endpoint.'",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({cap:c,t:"'.$t.'"})});let d=await r.json();if(!r.ok||!d.ok)throw Error(d.detail||"Verification failed");location.href=d.redirect||(d.sid?"/p?s="+d.sid:"/")}catch(e){alert(e.message);btn.disabled=false}}</script></body></html>';}
