  if($path==='/admin/stats'&&$method==='GET'){$sum=pdo()->query('SELECT COUNT(*) total_urls,COALESCE(SUM(clicks),0) total_clicks,COALESCE(SUM(visits),0) total_visits,COALESCE(SUM(blocked),0) total_blocked,COALESCE(SUM(bots),0) total_bots,COALESCE(SUM(captcha_fails),0) total_captcha_fails FROM urls')->fetch();$timeline=pdo()->query("SELECT DATE_FORMAT(ts,'%Y-%m-%d') _id,COUNT(*) count FROM visits WHERE ts>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 7 DAY) GROUP BY DATE(ts) ORDER BY DATE(ts)")->fetchAll();$hourly=pdo()->query("SELECT HOUR(ts) _id,COUNT(*) count FROM visits WHERE ts>=UTC_DATE() AND status='success' GROUP BY HOUR(ts) ORDER BY HOUR(ts)")->fetchAll();$grp=fn($f)=>pdo()->query("SELECT $f _id,COUNT(*) count FROM visits GROUP BY $f ORDER BY count DESC LIMIT 10")->fetchAll();out(['summary'=>$sum,'timeline'=>$timeline,'hourly'=>$hourly,'devices'=>$grp('device'),'browsers'=>$grp('browser'),'statuses'=>$grp('status'),'top_ips'=>pdo()->query('SELECT ip _id,COUNT(*) count FROM visits GROUP BY ip ORDER BY count DESC LIMIT 10')->fetchAll(),'blocked_ips'=>pdo()->query('SELECT * FROM blocked LIMIT 100')->fetchAll(),'recent_bots'=>pdo()->query("SELECT * FROM visits WHERE status='bot' ORDER BY ts DESC LIMIT 20")->fetchAll(),'bot_reasons'=>pdo()->query("SELECT reason _id,COUNT(*) count FROM visits WHERE status='bot' GROUP BY reason ORDER BY count DESC LIMIT 10")->fetchAll()]);}
 }
 err('Not found',404);
}catch(Throwable $e){error_log('[TeamDev PHP] '.$e->getMessage());err(ev('APP_DEBUG')==='1'?$e->getMessage():'Internal server error',500);}
